from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        names = sorted(packages, reverse=(name_order == "descending"))
        best_vector = None
        best_versions = None

        def acyclic(edges):
            done = set()
            active = set()

            def visit(node):
                if node in active:
                    return False
                if node in done:
                    return True
                active.add(node)
                for other in edges.get(node, ()):
                    if not visit(other):
                        return False
                active.remove(node)
                done.add(node)
                return True

            return all(visit(node) for node in edges)

        def search(chosen, requirements, edges):
            nonlocal best_vector, best_versions
            for name, ranges in requirements.items():
                if name in chosen and any(not low <= chosen[name] <= high
                                          for low, high in ranges):
                    return

            unresolved = [name for name in requirements if name not in chosen]
            if not unresolved:
                if not acyclic(edges):
                    return
                vector = tuple(chosen.get(name, -1) for name in names)
                if (best_vector is None or
                        (vector > best_vector if preference == "maximum"
                         else vector < best_vector)):
                    best_vector = vector
                    best_versions = dict(chosen)
                return

            name = unresolved[0]
            ranges = requirements[name]
            rows = [row for row in packages[name]
                    if all(low <= row["version"] <= high for low, high in ranges)
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            rows.sort(key=lambda row: row["version"], reverse=(preference == "maximum"))
            for row in rows:
                version = row["version"]
                next_chosen = dict(chosen)
                next_chosen[name] = version
                next_requirements = {key: list(value)
                                     for key, value in requirements.items()}
                next_edges = {key: list(value) for key, value in edges.items()}
                next_edges.setdefault(name, [])
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    next_requirements.setdefault(target, []).append(
                        (dep["min"], dep["max"]))
                    next_edges[name].append(target)
                search(next_chosen, next_requirements, next_edges)

        roots = {name: [tuple(bounds)] for name, bounds in data["roots"].items()}
        search({}, roots, {})
        return ({"versions": best_versions} if best_versions is not None
                else {"error": "unsatisfiable"})

    return solve


def _ledger_solver(data):
    def rounded(numerator, mode):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), mode)
        tax = rounded(raw * event.get("tax_bp", 0), mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = (event.get("account", "default") + "|" +
               event.get("currency", "USD"))
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_solver(data):
    from collections import Counter
    from itertools import combinations
    import heapq

    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    jobs = [job for job in data["jobs"] if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in subset)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ends = []
        valid = True
        for job in sorted(subset, key=lambda item: (item["start"], item["end"],
                                                     item["id"])):
            while ends and ends[0] <= job["start"]:
                heapq.heappop(ends)
            heapq.heappush(ends, job["end"])
            if len(ends) > 2:
                valid = False
                break
        if not valid:
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _route_solver(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << index for index, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            for duration, next_remaining in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask,
                                           next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _dependency_solver("maximum", "descending"),
    "component_02": _dependency_solver("minimum", "descending"),
    "component_03": _dependency_solver("maximum", "ascending"),
    "component_04": _dependency_solver("minimum", "ascending"),
    "component_05": _dependency_solver("maximum", "descending"),
    "component_06": _ledger_solver,
    "component_07": _quota_solver,
    "component_08": _route_solver,
}
